import React from 'react';
import { useAuth } from '../../context/AuthContext';
import './Sidebar.css';

const Sidebar = ({ isOpen, onClose, setActiveView }) => {
  const { user } = useAuth();

  const menuItems = [
    { id: 'shipments', label: 'Shipments', icon: '📦', submenu: ['All Shipments', 'Pending', 'In Transit', 'Delivered'] },
    { id: 'analytics', label: 'Analytics', icon: '📊', submenu: ['Overview', 'Performance', 'Trends'] },
    { id: 'reports', label: 'Reports', icon: '📄', submenu: ['Daily Reports', 'Weekly Reports', 'Monthly Reports'] },
    { id: 'settings', label: 'Settings', icon: '⚙️', submenu: ['Profile', 'Preferences', 'Notifications'] },
  ];

  // Admin-only menu items
  const adminMenuItems = [
    { id: 'users', label: 'User Management', icon: '👥', adminOnly: true },
  ];

  const [expandedItem, setExpandedItem] = React.useState(null);

  const handleItemClick = (itemId) => {
    if (expandedItem === itemId) {
      setExpandedItem(null);
    } else {
      setExpandedItem(itemId);
    }
    setActiveView(itemId);
  };

  const handleSubmenuClick = (itemId, submenuItem) => {
    setActiveView(itemId);
    onClose();
  };

  return (
    <>
      {isOpen && <div className="sidebar-overlay" onClick={onClose} />}
      <aside className={`sidebar ${isOpen ? 'open' : ''}`}>
        <div className="sidebar-header">
          <h2>🚚 TMS</h2>
          <button className="close-btn" onClick={onClose}>×</button>
        </div>
        <nav className="sidebar-nav">
          {menuItems.map((item) => (
            <div key={item.id} className="nav-item">
              <div
                className="nav-item-header"
                onClick={() => handleItemClick(item.id)}
              >
                <span className="nav-icon">{item.icon}</span>
                <span className="nav-label">{item.label}</span>
                {item.submenu && (
                  <span className="nav-arrow">{expandedItem === item.id ? '▼' : '▶'}</span>
                )}
              </div>
              {item.submenu && expandedItem === item.id && (
                <ul className="submenu">
                  {item.submenu.map((subItem, index) => (
                    <li
                      key={index}
                      className="submenu-item"
                      onClick={() => handleSubmenuClick(item.id, subItem)}
                    >
                      {subItem}
                    </li>
                  ))}
                </ul>
              )}
            </div>
          ))}
        </nav>
        <div className="sidebar-footer">
          <div className="user-info">
            <div className="user-avatar">{user?.username?.charAt(0).toUpperCase()}</div>
            <div className="user-details">
              <div className="user-name">{user?.username}</div>
              <div className="user-role">{user?.role}</div>
            </div>
          </div>
        </div>
      </aside>
    </>
  );
};

export default Sidebar;
